public class VolumeCalculator {
    private List<SolidShape> shapes;

    public VolumeCalculator(List<SolidShape> shapes) {
        this.shapes = shapes;
    }

    public double sum() {
        double totalVolume = 0;
        for (SolidShape shape : shapes) {
            totalVolume += shape.volume();
        }
        return totalVolume;
    }
}

